q=deque(); comp=set()
for r in range(R):
 for c in range(C):
  if g[r][c]==6:
   for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
    rr,cc=r+dr,c+dc
    if 0<=rr<R and 0<=cc<C and g[rr][cc]==8 and (rr,cc) not in comp:
     comp.add((rr,cc));q.append((rr,cc))
while q:
 r,c=q.popleft()
 for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
  rr,cc=r+dr,c+dc
  if 0<=rr<R and 0<=cc<C and g[rr][cc]==8 and (rr,cc) not in comp:
   comp.add((rr,cc));q.append((rr,cc))
out2=[row[:] for row in g]
for r,c in comp:
 border=r in (0,R-1) or c in (0,C-1)
 near1=any(0<=r+dr<R and 0<=c+dc<C and g[r+dr][c+dc]==1 for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)))
 if border or near1:out2[r][c]=7
